BEGIN;
CREATE TABLE curriculum_resource_requirements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),course_id uuid NOT NULL,category text NOT NULL CHECK(category IN ('textbook','workbook','software','calculator','reference','supply','accessibility_tool','lab')),description text NOT NULL,required boolean NOT NULL DEFAULT true,cost_disclosure text,approved_by uuid REFERENCES users(id),effective_term text NOT NULL);
CREATE TABLE assessment_blueprints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),course_id uuid NOT NULL,version integer NOT NULL,status text NOT NULL CHECK(status IN ('draft','faculty_review','approved','retired')),target_item_count integer NOT NULL DEFAULT 221 CHECK(target_item_count=221),outcome_weights jsonb NOT NULL,cognitive_level_weights jsonb NOT NULL,item_type_weights jsonb NOT NULL,approved_by uuid REFERENCES users(id),effective_at timestamptz,UNIQUE(tenant_id,course_id,version),CHECK(status<>'approved' OR approved_by IS NOT NULL));
CREATE TABLE assessment_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),blueprint_id uuid NOT NULL REFERENCES assessment_blueprints(id),item_type text NOT NULL CHECK(item_type IN ('single_choice','multiple_select','numeric_calculation','scenario','case_analysis','short_response','writing','discussion','practical','oral_defense')),prompt text NOT NULL,response_schema jsonb NOT NULL,rubric jsonb,correct_response_encrypted bytea,rationale text,source_citations jsonb NOT NULL DEFAULT '[]',difficulty numeric(4,3),discrimination numeric(5,4),status text NOT NULL CHECK(status IN ('draft','content_review','accessibility_review','approved','retired','compromised')),authored_by uuid NOT NULL REFERENCES users(id),approved_by uuid REFERENCES users(id),version integer NOT NULL DEFAULT 1,CHECK(status<>'approved' OR approved_by IS NOT NULL));
CREATE TABLE assessment_definitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),course_id uuid NOT NULL,title text NOT NULL,kind text NOT NULL CHECK(kind IN ('quiz','exam','midterm','final','writing','discussion','case_study','extra_credit','test_out','standardized','practical')),blueprint_id uuid REFERENCES assessment_blueprints(id),points_possible numeric(10,2) NOT NULL CHECK(points_possible>0),time_limit_minutes integer,attempt_limit integer NOT NULL DEFAULT 1 CHECK(attempt_limit>0),proctoring_level text NOT NULL CHECK(proctoring_level IN ('none','identity_check','live','recorded_review','testing_center')),human_approval_required boolean NOT NULL DEFAULT true,published_at timestamptz);
CREATE TABLE assessment_forms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),assessment_id uuid NOT NULL REFERENCES assessment_definitions(id),form_code text NOT NULL,item_manifest jsonb NOT NULL,manifest_hash text NOT NULL,generated_at timestamptz NOT NULL DEFAULT now(),approved_by uuid REFERENCES users(id),UNIQUE(assessment_id,form_code));
CREATE TABLE secure_assessment_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),assessment_id uuid NOT NULL REFERENCES assessment_definitions(id),form_id uuid NOT NULL REFERENCES assessment_forms(id),student_user_id uuid NOT NULL REFERENCES users(id),started_at timestamptz,submitted_at timestamptz,status text NOT NULL CHECK(status IN ('authorized','started','submitted','grading','review','released','voided')),accommodation_snapshot jsonb NOT NULL DEFAULT '{}',integrity_flags jsonb NOT NULL DEFAULT '[]',released_by uuid REFERENCES users(id),UNIQUE(assessment_id,student_user_id,form_id));
CREATE TABLE attempt_responses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),attempt_id uuid NOT NULL REFERENCES secure_assessment_attempts(id),item_id uuid NOT NULL REFERENCES assessment_items(id),response jsonb NOT NULL,auto_score numeric(10,2),human_score numeric(10,2),scored_by uuid REFERENCES users(id),feedback text,UNIQUE(attempt_id,item_id));
CREATE TABLE assessment_proctoring_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),attempt_id uuid NOT NULL REFERENCES secure_assessment_attempts(id),provider text NOT NULL,external_session_id text,consent_at timestamptz,started_at timestamptz,ended_at timestamptz,review_status text NOT NULL CHECK(review_status IN ('not_required','pending','clear','flagged','appealed','resolved')),evidence_key text,reviewed_by uuid REFERENCES users(id),retention_until timestamptz,UNIQUE(attempt_id));
CREATE INDEX assessment_item_pool ON assessment_items(tenant_id,blueprint_id,item_type,status);CREATE INDEX secure_attempt_student_idx ON secure_assessment_attempts(tenant_id,student_user_id,status);CREATE INDEX assessment_proctor_review_idx ON assessment_proctoring_sessions(tenant_id,review_status);
ALTER TABLE curriculum_resource_requirements ENABLE ROW LEVEL SECURITY;ALTER TABLE assessment_blueprints ENABLE ROW LEVEL SECURITY;ALTER TABLE assessment_items ENABLE ROW LEVEL SECURITY;ALTER TABLE assessment_definitions ENABLE ROW LEVEL SECURITY;ALTER TABLE assessment_forms ENABLE ROW LEVEL SECURITY;ALTER TABLE secure_assessment_attempts ENABLE ROW LEVEL SECURITY;ALTER TABLE attempt_responses ENABLE ROW LEVEL SECURITY;ALTER TABLE assessment_proctoring_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY curriculum_resource_tenant ON curriculum_resource_requirements USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY assessment_blueprint_tenant ON assessment_blueprints USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY assessment_item_tenant ON assessment_items USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY assessment_definitions_tenant ON assessment_definitions USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY assessment_forms_tenant ON assessment_forms USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY secure_assessment_attempts_tenant ON secure_assessment_attempts USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY attempt_responses_tenant ON attempt_responses USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY assessment_proctoring_tenant ON assessment_proctoring_sessions USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
